{
  description = "Personal workstation Home Manager configuration";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    dotnet-nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    home-manager = {
      url = "github:nix-community/home-manager/master";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    hermes-agent.url = "github:NousResearch/hermes-agent";
    nix-openclaw = {
      url = "github:openclaw/nix-openclaw";
      inputs.nixpkgs.follows = "nixpkgs";
      inputs.home-manager.follows = "home-manager";
    };
  };

  outputs =
    {
      nixpkgs,
      dotnet-nixpkgs,
      home-manager,
      hermes-agent,
      nix-openclaw,
      ...
    }:
    let
      system = "x86_64-linux";
      openclawOverlay = import "${nix-openclaw}/nix/overlay.nix" {
        openclawToolPkgs = nix-openclaw.inputs.nix-openclaw-tools.packages.${system};
      };
      pkgs = import nixpkgs {
        inherit system;
        overlays = [ openclawOverlay ];
        config.allowUnfree = true;
      };
      dotnetPkgs = import dotnet-nixpkgs {
        inherit system;
      };
      dotnetSdk = dotnetPkgs.dotnet-sdk_10;
      morainePackage = pkgs.callPackage ./packages/moraine.nix { };
      behavioralTestInputs = [
        pkgs.bash
        pkgs.chezmoi
        pkgs.coreutils
        pkgs.diffutils
        pkgs.findutils
        pkgs.git
        pkgs.gnugrep
        pkgs.gnused
        pkgs.jq
        pkgs.nix
        pkgs.unzip
        pkgs.util-linux
        pkgs.zip
      ];
      behavioralTestSource = nixpkgs.lib.fileset.toSource {
        root = ./.;
        fileset = ./.;
      };
      workstationHomeConfiguration = home-manager.lib.homeManagerConfiguration {
        inherit pkgs;
        extraSpecialArgs = {
          inherit dotnetSdk morainePackage;
          hermesPackage = hermes-agent.packages.${system}.default;
        };
        modules = [
          nix-openclaw.homeManagerModules.openclaw
          ./home/workstation.nix
        ];
      };
      bootstrapAgentToolsActivation = pkgs.writeText "bootstrap-agent-tools" (
        workstationHomeConfiguration.config.home.activation.bootstrapAgentTools.data
      );
      bootstrapAgentToolsOrdering = pkgs.writeText "bootstrap-agent-tools-after" (
        builtins.toJSON workstationHomeConfiguration.config.home.activation.bootstrapAgentTools.after
      );
      workstationRenderedConfiguration = pkgs.writeText "workstation-rendered-configuration.json" (
        builtins.toJSON {
          dotnetSdkPackage =
            let
              package = builtins.head (
                builtins.filter
                  (package: (package.pname or package.name) == "dotnet-sdk-wrapped")
                  workstationHomeConfiguration.config.home.packages
              );
            in
            {
              pname = package.pname or package.name;
              inherit (package) version;
            };
          moraineRelease = {
            inherit (morainePackage) version;
            hash = morainePackage.src.outputHash;
            source = morainePackage.src.url;
            storePath = "${morainePackage}";
            hasReleasePassthru = morainePackage.passthru ? release;
          };
          moraineConfig = builtins.fromTOML (builtins.unsafeDiscardStringContext (
            workstationHomeConfiguration.config.home.file.".moraine/config.toml".text
          ));
          moraineServiceTopology =
            let
              services = workstationHomeConfiguration.config.systemd.user.services;
            in
            {
              names = builtins.filter
                (name: builtins.match "moraine.*" name != null)
                (builtins.attrNames services);
              service = services.moraine;
            };
          moraineCodexBoundary = {
            managesConfig = workstationHomeConfiguration.config.home.file ? ".codex/config.toml";
            hasRegistrationActivation =
              workstationHomeConfiguration.config.home.activation ? configureMoraineCodexMcp;
          };
          collieOriginSocket =
            workstationHomeConfiguration.config.systemd.user.sockets.collie-origin-forwarder;
          collieOriginService =
            workstationHomeConfiguration.config.systemd.user.services.collie-origin-forwarder;
          aoeLanProxySocket = workstationHomeConfiguration.config.systemd.user.sockets.aoe-lan-proxy;
          aoeLanProxyService = workstationHomeConfiguration.config.systemd.user.services.aoe-lan-proxy;
          aoeServeService = workstationHomeConfiguration.config.systemd.user.services.aoe-serve;
          herdrService = workstationHomeConfiguration.config.systemd.user.services.herdr;
          workstationActivation = builtins.mapAttrs (
            _: entry: entry.data or ""
          ) workstationHomeConfiguration.config.home.activation;
          collieServiceDropIn =
            workstationHomeConfiguration.config.xdg.configFile
            ."systemd/user/collie.service.d/10-origin-forwarder.conf".text;
        }
      );
      shellcheckSource = nixpkgs.lib.fileset.toSource {
        root = ./.;
        fileset = nixpkgs.lib.fileset.unions [
          ./.chezmoiscripts
          ./dot_bash_profile.tmpl
          ./dot_bashrc.tmpl
          ./dot_local/bin/executable_update-agent-tools
          ./dot_local/bin/executable_workstation-login
          ./dot_local/bin/executable_workstation-update
          ./scripts/moraine-service
          ./scripts/run-shellcheck
          ./scripts/run-tests
          ./scripts/update-dotnet-sdk
          ./tests
        ];
      };
      shellcheckCommand = pkgs.writeShellApplication {
        name = "dotfiles-shellcheck";
        runtimeInputs = [
          pkgs.chezmoi
          pkgs.shellcheck
        ];
        text = ''
          exec ${pkgs.bash}/bin/bash ${./scripts/run-shellcheck} ${shellcheckSource}
        '';
      };
    in
    {
      packages.${system} = {
        dotnet-sdk = dotnetSdk;
        moraine = morainePackage;
      };

      apps.${system}.shellcheck = {
        type = "app";
        program = "${shellcheckCommand}/bin/dotfiles-shellcheck";
      };

      checks.${system} = {
        github-actions = pkgs.runCommand "github-actions" {
          nativeBuildInputs = [ pkgs.actionlint ];
        } ''
          actionlint ${./.github/workflows/update-dotnet-sdk.yml}
          touch "$out"
        '';

        dotnet-sdk-major = dotnetPkgs.runCommand "dotnet-sdk-major" {
          nativeBuildInputs = [ dotnetSdk ];
        } ''
          export DOTNET_CLI_HOME="$TMPDIR/dotnet-home"
          export DOTNET_SKIP_FIRST_TIME_EXPERIENCE=1
          mkdir -p "$DOTNET_CLI_HOME"

          _dotnet_version="$(dotnet --version)"
          case "$_dotnet_version" in
            10.*) ;;
            *)
              echo "Expected a .NET 10 SDK, got $_dotnet_version" >&2
              exit 1
              ;;
          esac

          touch "$out"
        '';

        workstation-activation = workstationHomeConfiguration.activationPackage;

        shellcheck = pkgs.runCommand "dotfiles-shellcheck" {
          nativeBuildInputs = [
            pkgs.chezmoi
            pkgs.shellcheck
          ];
        } ''
          ${pkgs.bash}/bin/bash ${./scripts/run-shellcheck} ${shellcheckSource}
          touch "$out"
        '';

        test-runner = pkgs.runCommand "dotfiles-test-runner" {
          nativeBuildInputs = behavioralTestInputs;
        } ''
          export HOME="$TMPDIR/home"
          export XDG_CACHE_HOME="$TMPDIR/cache"
          export XDG_CONFIG_HOME="$TMPDIR/config"
          export XDG_STATE_HOME="$TMPDIR/state"
          mkdir -p "$HOME" "$XDG_CACHE_HOME" "$XDG_CONFIG_HOME" "$XDG_STATE_HOME"

          ${pkgs.bash}/bin/bash ${behavioralTestSource}/tests/contracts/test-runner.bash
          touch "$out"
        '';

        behavioral-tests = pkgs.runCommand "dotfiles-behavioral-tests" {
          nativeBuildInputs = behavioralTestInputs;
          NIX_CONFIG = ''
            experimental-features = nix-command flakes
            offline = true
          '';
          TEST_BOOTSTRAP_ACTIVATION_SCRIPT = bootstrapAgentToolsActivation;
          TEST_BOOTSTRAP_ACTIVATION_AFTER = bootstrapAgentToolsOrdering;
          TEST_WORKSTATION_RENDERED_CONFIGURATION = workstationRenderedConfiguration;
        } ''
          export HOME="$TMPDIR/home"
          export XDG_CACHE_HOME="$TMPDIR/cache"
          export XDG_CONFIG_HOME="$TMPDIR/config"
          export XDG_STATE_HOME="$TMPDIR/state"
          mkdir -p "$HOME" "$XDG_CACHE_HOME" "$XDG_CONFIG_HOME" "$XDG_STATE_HOME"

          ${pkgs.bash}/bin/bash ${behavioralTestSource}/scripts/run-tests
          touch "$out"
        '';
      };

      devShells.${system}.default = pkgs.mkShell {
        packages = behavioralTestInputs ++ [ pkgs.shellcheck ];
      };

      homeConfigurations.workstation = workstationHomeConfiguration;
    };
}
#!/usr/bin/env bash
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
readonly REPO_ROOT

fail() {
  printf 'FAIL: %s\n' "$*" >&2
  exit 1
}

rendered_json() {
  local fixture_filter="$1"
  local installable="$2"
  shift 2

  if [[ -n "${TEST_WORKSTATION_RENDERED_CONFIGURATION:-}" ]]; then
    jq -ce "$fixture_filter" "$TEST_WORKSTATION_RENDERED_CONFIGURATION"
    return
  fi

  nix eval --json "$installable" "$@"
}

rendered_herdr_service() {
  rendered_json '.herdrService' \
    "$REPO_ROOT#homeConfigurations.workstation.config.systemd.user.services.herdr"
}

rendered_workstation_activation() {
  rendered_json '.workstationActivation' \
    "$REPO_ROOT#homeConfigurations.workstation.config.home.activation" \
    --apply 'activation: builtins.mapAttrs (_: entry: entry.data or "") activation'
}

test_herdr_service_runs_the_supported_foreground_server() {
  local rendered_service

  rendered_service="$(rendered_herdr_service)" \
    || fail 'could not render the Herdr user service'

  jq -e \
    '.Service.ExecStart == ["/home/faviann/.local/bin/herdr server"]' \
    <<<"$rendered_service" >/dev/null \
    || fail 'Herdr does not execute the supported foreground server entrypoint directly'
}

test_herdr_service_has_a_deterministic_process_environment() {
  local rendered_service

  rendered_service="$(rendered_herdr_service)" \
    || fail 'could not render the Herdr user service'

  jq -e '
    (.Service.Type == "simple") and
    (.Service.ExecStart == ["/home/faviann/.local/bin/herdr server"]) and
    (.Service.WorkingDirectory == "/home/faviann") and
    (.Service.Environment == [
      "PATH=/home/faviann/.local/bin:/home/faviann/.nix-profile/bin:/usr/local/bin:/usr/bin:/bin"
    ])
  ' <<<"$rendered_service" >/dev/null \
    || fail 'Herdr service process environment is not deterministic and self-contained'
}

test_herdr_service_restarts_failures_after_a_bounded_delay() {
  local rendered_service

  rendered_service="$(rendered_herdr_service)" \
    || fail 'could not render the Herdr user service'

  jq -e '
    (.Service.Restart == "on-failure") and
    (.Service.RestartSec == 5)
  ' <<<"$rendered_service" >/dev/null \
    || fail 'Herdr service does not use its bounded failure-restart policy'
}

test_herdr_service_leaves_normal_termination_to_herdr() {
  local rendered_service

  rendered_service="$(rendered_herdr_service)" \
    || fail 'could not render the Herdr user service'

  jq -e '
    (.Service.Type == "simple") and
    (.Service.ExecStart == ["/home/faviann/.local/bin/herdr server"]) and
    (.Service | has("ExecStop") | not) and
    (.Service | has("PIDFile") | not) and
    (.Service | has("NotifyAccess") | not)
  ' <<<"$rendered_service" >/dev/null \
    || fail 'Herdr service overrides the foreground server graceful-termination contract'
}

test_herdr_service_is_staged_without_target_or_activation() {
  local rendered_activation
  local rendered_service

  rendered_service="$(rendered_herdr_service)" \
    || fail 'could not render the Herdr user service'
  rendered_activation="$(rendered_workstation_activation)" \
    || fail 'could not render the workstation activation configuration'

  jq -e '(.Install.WantedBy // []) == []' <<<"$rendered_service" >/dev/null \
    || fail 'Herdr service is enabled in a user target'
  jq -e \
    '[to_entries[] | select(.value | test("herdr.*(start|enable)|(start|enable).*herdr"; "i"))] == []' \
    <<<"$rendered_activation" >/dev/null \
    || fail 'workstation activation starts or enables Herdr'
}

test_herdr_staging_does_not_take_over_the_detached_server_or_panes() {
  local rendered_activation
  local rendered_service

  rendered_service="$(rendered_herdr_service)" \
    || fail 'could not render the Herdr user service'
  rendered_activation="$(rendered_workstation_activation)" \
    || fail 'could not render the workstation activation configuration'

  jq -e '
    (.Install.WantedBy // []) == [] and
    ((.Unit.Requires // []) == []) and
    ((.Unit.BindsTo // []) == []) and
    ((.Unit.PartOf // []) == []) and
    (.Service | has("ExecStop") | not) and
    (.Service | has("ExecReload") | not) and
    (.Service | has("KillSignal") | not) and
    ([.Service | .. | strings | select(test("--daemon|pid.file|migrat|pane|session"; "i"))] == [])
  ' <<<"$rendered_service" >/dev/null \
    || fail 'staged Herdr unit takes ownership of the detached server or its panes'
  jq -e \
    '[to_entries[] | select(.value | test("herdr"; "i"))] == []' \
    <<<"$rendered_activation" >/dev/null \
    || fail 'workstation activation contains a Herdr lifecycle or migration action'
}

test_workstation_herdr_documentation_explains_the_deferred_cutover() {
  local herdr_section
  local normalized_section

  herdr_section="$(
    sed -n '/^## Workstation herdr$/,$p' "$REPO_ROOT/README.md"
  )" || fail 'could not read the Workstation herdr operating section'
  normalized_section="${herdr_section//$'\n'/ }"

  grep -Eiq 'activation[^.]*deferred[^.]*cutover|deferred[^.]*activation[^.]*cutover' \
    <<<"$normalized_section" \
    || fail 'Workstation herdr documentation does not defer activation to cutover'
  grep -Fiq 'server shutdown ends pane processes' <<<"$normalized_section" \
    || fail 'Workstation herdr documentation does not explain the pane-process risk'
}

# shellcheck source=tests/lib/suite-dispatch.bash
source "$REPO_ROOT/tests/lib/suite-dispatch.bash"

readonly test_cases=(
  test_herdr_service_runs_the_supported_foreground_server
  test_herdr_service_has_a_deterministic_process_environment
  test_herdr_service_restarts_failures_after_a_bounded_delay
  test_herdr_service_leaves_normal_termination_to_herdr
  test_herdr_service_is_staged_without_target_or_activation
  test_herdr_staging_does_not_take_over_the_detached_server_or_panes
  test_workstation_herdr_documentation_explains_the_deferred_cutover
)

suite_dispatch 'workstation Herdr supervised-service staging' "$@"
#!/usr/bin/env bash

# test_cases is the suite-owned public case registry.
# shellcheck disable=SC2154
suite_dispatch() {
  local pass_message="$1"
  local requested_case
  local test_case
  shift

  if (( $# == 1 )) && [[ "$1" == --list ]]; then
    printf '%s\n' "${test_cases[@]}"
    return 0
  fi

  if (( $# == 2 )) && [[ "$1" == --case && -n "$2" ]]; then
    requested_case="$2"
    for test_case in "${test_cases[@]}"; do
      if [[ "$test_case" == "$requested_case" ]]; then
        "$test_case"
        trap - RETURN
        printf 'PASS: %s\n' "$pass_message"
        return 0
      fi
    done
    printf 'ERROR: unknown test case: %s\n' "$requested_case" >&2
    return 2
  fi

  if (( $# != 0 )); then
    printf 'Usage: %s [--list | --case EXACT_NAME]\n' "$0" >&2
    return 2
  fi

  for test_case in "${test_cases[@]}"; do
    "$test_case"
    trap - RETURN
  done
  printf 'PASS: %s\n' "$pass_message"
}
#!/usr/bin/env bash
set -uo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
readonly REPO_ROOT

fail() {
  printf 'ERROR: %s\n' "$*" >&2
  exit 2
}

readonly required_commands=(
  bash
  basename
  cat
  chezmoi
  chmod
  cp
  cut
  date
  diff
  dirname
  env
  find
  flock
  git
  git-upload-pack
  grep
  head
  install
  jq
  ln
  mkdir
  mktemp
  mv
  nix
  rm
  script
  sed
  sha256sum
  sleep
  sort
  stat
  tail
  tr
  unzip
  wc
  zip
)

missing_commands=()
for required_command in "${required_commands[@]}"; do
  command -v "$required_command" >/dev/null 2>&1 \
    || missing_commands+=("$required_command")
done
(( ${#missing_commands[@]} == 0 )) \
  || fail "required test dependencies not found in PATH: ${missing_commands[*]}"

# Invoked indirectly by the signal trap during a full run.
# shellcheck disable=SC2329
handle_interruption() {
  local child_pid

  trap - HUP INT TERM
  for child_pid in "${pids[@]}"; do
    kill -TERM -- "-$child_pid" 2>/dev/null || true
  done
  for child_pid in "${pids[@]}"; do
    wait "$child_pid" 2>/dev/null || true
  done
  exit 130
}

shopt -s nullglob
suites=("$REPO_ROOT"/tests/*.bash)
(( ${#suites[@]} > 0 )) || fail 'no test suites found'

declare -a cases=()
declare -A case_owner=()
declare -A suite_path_by_name=()
for suite_path in "${suites[@]}"; do
  suite_name="$(basename "$suite_path")"
  suite_path_by_name["$suite_name"]="$suite_path"
  if ! suite_cases="$(bash "$suite_path" --list)"; then
    fail "could not list cases for suite: $suite_name"
  fi
  while IFS= read -r test_case; do
    [[ -n "$test_case" ]] || continue
    if [[ -n "${case_owner[$test_case]:-}" ]]; then
      fail "ambiguous test case: $test_case"
    fi
    case_owner["$test_case"]="$suite_path"
    cases+=("$test_case")
  done <<<"$suite_cases"
done

if (( $# == 1 )) && [[ "$1" == --list ]]; then
  printf 'Suites:\n'
  for suite_path in "${suites[@]}"; do
    basename "$suite_path"
  done
  printf 'Cases:\n'
  printf '%s\n' "${cases[@]}"
  exit 0
fi

if (( $# == 2 )) && [[ "$1" == --suite && -n "$2" ]]; then
  selected_suite="${suite_path_by_name[$2]:-}"
  [[ -n "$selected_suite" ]] || fail "unknown test suite: $2"
  exec bash "$selected_suite"
fi

if (( $# == 2 )) && [[ "$1" == --case && -n "$2" ]]; then
  selected_suite="${case_owner[$2]:-}"
  [[ -n "$selected_suite" ]] || fail "unknown test case: $2"
  exec bash "$selected_suite" --case "$2"
fi

if (( $# == 0 )); then
  run_dir="$(mktemp -d "${TMPDIR:-/tmp}/dotfiles-tests.XXXXXX")" \
    || fail 'could not create temporary logging directory'
  trap 'rm -rf "$run_dir"' EXIT
  pids=()
  trap handle_interruption HUP INT TERM
  overall_start_ms="$(date +%s%3N)"
  starts_ms=()
  statuses=()
  durations_ms=()
  declare -A suite_index_by_pid=()
  set -m
  for suite_index in "${!suites[@]}"; do
    suite_path="${suites[$suite_index]}"
    starts_ms[suite_index]="$(date +%s%3N)"
    bash "$suite_path" >"$run_dir/$suite_index.log" 2>&1 &
    child_pid="$!"
    pids+=("$child_pid")
    suite_index_by_pid["$child_pid"]="$suite_index"
  done
  set +m

  aggregate_status=0
  passed_count=0
  failed_count=0
  remaining_count="${#pids[@]}"
  while (( remaining_count > 0 )); do
    completed_pid=
    if wait -n -p completed_pid; then
      completion_status=0
    else
      completion_status=$?
    fi
    [[ -n "$completed_pid" ]] \
      || fail 'could not identify a completed test suite'
    suite_index="${suite_index_by_pid[$completed_pid]}"
    if (( completion_status == 0 )); then
      statuses[suite_index]=0
      passed_count=$((passed_count + 1))
    else
      statuses[suite_index]="$completion_status"
      aggregate_status=1
      failed_count=$((failed_count + 1))
    fi
    end_ms="$(date +%s%3N)"
    durations_ms[suite_index]=$((end_ms - starts_ms[suite_index]))
    remaining_count=$((remaining_count - 1))
  done

  if (( failed_count > 0 )); then
    printf 'Failures:\n'
    for suite_index in "${!suites[@]}"; do
      (( statuses[suite_index] != 0 )) || continue
      suite_name="$(basename "${suites[$suite_index]}")"
      printf '===== %s (status %s) =====\n' \
        "$suite_name" "${statuses[$suite_index]}"
      cat "$run_dir/$suite_index.log"
      printf '===== end %s =====\n' "$suite_name"
    done
  fi

  printf 'Results:\n'
  for suite_index in "${!suites[@]}"; do
    suite_name="$(basename "${suites[$suite_index]}")"
    if (( statuses[suite_index] == 0 )); then
      printf 'PASS %s (%sms)\n' \
        "$suite_name" "${durations_ms[$suite_index]}"
    else
      printf 'FAIL %s (%sms, status %s)\n' \
        "$suite_name" \
        "${durations_ms[$suite_index]}" \
        "${statuses[$suite_index]}"
    fi
  done
  overall_end_ms="$(date +%s%3N)"
  overall_duration_ms=$((overall_end_ms - overall_start_ms))
  if (( aggregate_status == 0 )); then
    printf 'Overall: PASS (%s passed, 0 failed, %sms)\n' \
      "$passed_count" "$overall_duration_ms"
  else
    printf 'Overall: FAIL (%s passed, %s failed, %sms)\n' \
      "$passed_count" "$failed_count" "$overall_duration_ms"
  fi
  exit "$aggregate_status"
fi

fail "Usage: $0 [--list | --suite EXACT_NAME | --case EXACT_NAME]"

