function isStartable() {
  local service="$1"
  [[ $(systemctl --user show -p RefuseManualStart "$service") == *=no ]]
}

function isStoppable() {
  if [[ -v oldGenPath ]] ; then
    local service="$1"
    [[ $(systemctl --user show -p RefuseManualStop "$service") == *=no ]]
  fi
}

